const cvContent = $("Create Tailored CV Content").item.json;

const cvPdf = $("Upload CV PDF to Baserow").first().json;
const cvTex = $("Upload CV TEX to Baserow").first().json;
const coverPdf = $("Upload Cover Letter PDF to Baserow").first().json;
const coverTex = $("Upload Cover Letter TEX to Baserow").first().json;

const requiredUpload = (upload, label) => {
  if (!upload || typeof upload.name !== "string" || !upload.name.trim()) {
    throw new Error(`${label} did not return a valid Baserow user-file name.`);
  }
  return upload;
};

requiredUpload(cvPdf, "CV PDF upload");
requiredUpload(cvTex, "CV TEX upload");
requiredUpload(coverPdf, "Cover letter PDF upload");
requiredUpload(coverTex, "Cover letter TEX upload");

const rowId = Number($("Prepare CV Content Input").item.json.baserow_row_id);
if (!Number.isInteger(rowId) || rowId <= 0) {
  throw new Error("The job context does not contain a valid Baserow row ID.");
}

const applicationId = String(cvContent.application_id ?? "application");

return [{
  json: {
    rowId,
    "Cover Letter": [
      {
        "name": coverPdf.name,
        "visible_name": `cover-letter_${applicationId}.pdf`
      },
      {
        "name": coverTex.name,
        "visible_name": `cover-letter_${applicationId}.tex`
      }
    ],
    "CV": [
      {
        "name": cvPdf.name,
        "visible_name": `cv_${applicationId}.pdf`
      },
      {
        "name": cvTex.name,
        "visible_name": `cv_${applicationId}.tex`
      }
    ]
  }
}];

const submission = $input.first().json ?? {};
const questions = submission.questions ?? {};

const FIELD_IDS = {
  entryType: "entryType",
  linkedinJobId: "6Ze685Zcm27s3sV6xAdg6w",
  companyName: "tccyk1pB8iRUf1NGCDbcP5",
  jobTitle: "mV2wYQbu1b1Jhf1gTDAbK8",
  jobDescription: "98TcaL2qnS8Y31TQxgZaZD",
  jobUrl: "1gZ3kT2Db3G3y2QhYfjT8X",
  location: "oc63gzWN4vxEJwx8nzZrAK",
  contractType: "g2VK5MiabTgDTUXGYhnV4q",
  publishedAt: "sYghUzUtSwi8T4yaReYefR",
  jobId: "2XDTXJHaY2BJEndo3EgEAV",
  pageContent: "uAXUdaYv4cjhWqtZiFYWc7",
};

const normalizeValue = (value) => {
  if (value === undefined || value === null) return "";

  if (Array.isArray(value)) {
    return value.map(normalizeValue).filter((item) => item !== "").join(", ");
  }

  if (typeof value === "object") {
    for (const key of ["value", "label", "name", "url", "text", "optionId", "id"]) {
      if (value[key] !== undefined && value[key] !== null) {
        return normalizeValue(value[key]);
      }
    }
    return JSON.stringify(value);
  }

  return String(value).trim();
};

const questionValue = (fieldId, expectedName) => {
  const direct = questions[fieldId];

  if (direct !== undefined) {
    if (direct && typeof direct === "object" && "value" in direct) {
      return normalizeValue(direct.value);
    }
    return normalizeValue(direct);
  }

  const match = Object.values(questions).find((question) => {
    if (!question || typeof question !== "object") return false;
    const name = normalizeValue(question.name ?? question.label);
    return name.toLowerCase() === expectedName.toLowerCase();
  });

  return match && typeof match === "object" && "value" in match
    ? normalizeValue(match.value)
    : normalizeValue(match);
};

const entryTypeRaw = questionValue(FIELD_IDS.entryType, "Entry Type");
const entryType =
  entryTypeRaw.toLowerCase() === "linkedin"
    ? "LinkedIn"
    : entryTypeRaw.toLowerCase() === "external"
      ? "External"
      : entryTypeRaw.toLowerCase() === "ai"
        ? "AI"
        : entryTypeRaw;

if (!["LinkedIn", "External", "AI"].includes(entryType)) {
  throw new Error(`Fillout submission has an invalid Entry Type: "${entryTypeRaw}".`);
}

const linkedinJobId = questionValue(FIELD_IDS.linkedinJobId, "LinkedIn Job ID")
  .replace(/\s+/g, "");

if (entryType === "LinkedIn" && !/^\d+$/.test(linkedinJobId)) {
  throw new Error("LinkedIn Job ID is required and must contain only digits.");
}

const linkedinJobUrl = linkedinJobId
  ? `https://www.linkedin.com/jobs/view/${linkedinJobId}`
  : "";

const parsed = {
  entryType,
  linkedinJobId,
  linkedinJobUrl,
  companyName: questionValue(FIELD_IDS.companyName, "Company Name"),
  jobTitle: questionValue(FIELD_IDS.jobTitle, "Job Title"),
  jobDescription: questionValue(FIELD_IDS.jobDescription, "Job Description"),
  jobUrl: questionValue(FIELD_IDS.jobUrl, "Job URL"),
  location: questionValue(FIELD_IDS.location, "Location"),
  contractType: questionValue(FIELD_IDS.contractType, "Contract Type"),
  publishedAt: questionValue(FIELD_IDS.publishedAt, "Published Date"),
  jobId: entryType === "LinkedIn"
    ? linkedinJobId
    : questionValue(FIELD_IDS.jobId, "External Job ID"),
  pageContent: questionValue(FIELD_IDS.pageContent, "Page Content"),
};

if (entryType === "External") {
  for (const [field, label] of [
    ["companyName", "Company Name"],
    ["jobTitle", "Job Title"],
    ["jobDescription", "Job Description"],
    ["jobUrl", "Job URL"],
  ]) {
    if (!parsed[field]) {
      throw new Error(`${label} is required for External entries.`);
    }
  }
}

if (entryType === "AI" && !parsed.pageContent) {
  throw new Error("Page Content is required for AI entries.");
}

return [{
  json: {
    ...parsed,
    filloutSubmissionId: submission.submissionId ?? submission.id ?? "",
    filloutFormId: submission.formId ?? "",
    filloutSubmittedAt: submission.submissionTime ?? submission.createdAt ?? "",
  },
  pairedItem: { item: 0 },
}];

const resolved = $json;
const job = resolved.source_job ?? resolved;

const dateValue = job.publishedAt
  ? String(job.publishedAt).slice(0, 10)
  : new Date().toISOString().slice(0, 10);

return [{
  json: {
    rowId: resolved.baserow_row_id ?? null,
    record_exists: Boolean(resolved.record_exists),
    source_job: job,
    "Job ID": Number(job.jobId),
    "Date": dateValue,
    "Company Name": job.companyName ?? "",
    "Title": job.jobTitle ?? "",
    "Location": job.location ?? "",
    "Job Description": job.jobDescription ?? "",
    "Contract Type": job.contractType ?? "",
    "Link": job.jobUrl ?? "",
    "Status": "New"
  }
}];

const rowResult = $input.first().json;
const metadata = $("Build Initial Job Row").item.json;
const job = metadata.source_job;
const rowId = Number(rowResult?.id ?? metadata.rowId);

if (!Number.isInteger(rowId) || rowId <= 0) {
  throw new Error("The Baserow metadata upsert did not return a valid row ID.");
}

return [{
  json: {
    ...job,
    baserow_row_id: rowId
  }
}];

const job = $("Loop Over Jobs").item.json;
const targetJobId = String(job.jobId ?? "").trim();

if (!targetJobId) {
  throw new Error("Job ID is required to create or update a Baserow record.");
}

const matchingRows = $input.all()
  .map((item) => item.json?.fields && typeof item.json.fields === "object"
    ? { ...item.json.fields, id: item.json.id }
    : item.json)
  .filter((row) => String(row?.["Job ID"] ?? "").trim() === targetJobId);

if (matchingRows.length > 1) {
  throw new Error(`Multiple Baserow rows use Job ID ${targetJobId}.`);
}

const existing = matchingRows[0];

return [{
  json: {
    source_job: job,
    record_exists: Boolean(existing?.id),
    baserow_row_id: existing?.id ?? null
  }
}];

const extracted = $("Extract Master CV").first().json;
const form = $("Submit Job").first().json;
const response = $input.first().json;

const parseJson = (value) => {
  if (typeof value !== "string") return value;
  const cleaned = value.trim().replace(/^```(?:json)?\s*/i, "").replace(/\s*```$/, "");
  try {
    return JSON.parse(cleaned);
  } catch {
    return value;
  }
};

const unwrapMasterCv = (value) => {
  let current = parseJson(value);
  for (let depth = 0; depth < 5; depth++) {
    if (!current || typeof current !== "object" || Array.isArray(current)) break;
    if (Array.isArray(current.projects)) return current;
    const next = current.master_cv ?? current.cv_json ?? current.document_data ?? current.data ?? current.json;
    if (next === undefined || next === current) break;
    current = parseJson(next);
  }
  return current;
};

const text = (value) => String(value ?? "").trim();
const masterCv = unwrapMasterCv(extracted);
if (!masterCv || typeof masterCv !== "object" || Array.isArray(masterCv)) {
  throw new Error("The master CV file must contain a JSON object.");
}
if (!Array.isArray(masterCv.projects)) {
  throw new Error("The master CV JSON could not be normalized: projects must be an array.");
}

const rawContent = response?.choices?.[0]?.message?.content ?? response?.output ?? response?.text ?? response;
const fields = parseJson(rawContent);
if (!fields || typeof fields !== "object" || Array.isArray(fields)) {
  throw new Error("The AI job parser did not return a valid JSON object.");
}

const companyName = text(fields.companyName);
const jobTitle = text(fields.jobTitle);
const jobDescription = text(fields.jobDescription);
const jobUrl = text(fields.jobUrl);
if (!companyName) throw new Error("AI extraction could not identify the company name.");
if (!jobTitle) throw new Error("AI extraction could not identify the job title.");
if (!jobDescription) throw new Error("AI extraction could not identify the job description.");

const explicitId = text(fields.jobId).replace(/\D/g, "");
const urlId = (jobUrl.match(/(?:jobs?\/view\/|job(?:Id|ID|id)?[=\/-])(\d{5,})/i) || [])[1] ?? "";

const stableNumericId = (value) => {
  let h1 = 2166136261;
  let h2 = 2246822519;
  for (let i = 0; i < value.length; i++) {
    const c = value.charCodeAt(i);
    h1 = Math.imul(h1 ^ c, 16777619) >>> 0;
    h2 = Math.imul(h2 ^ c, 3266489917) >>> 0;
  }
  const combined = (BigInt(h1) << 21n) | BigInt(h2 & 0x1fffff);
  return Number((combined % 899999999999999n) + 100000000000000n);
};

const numericJobId = explicitId || urlId;
const jobId = numericJobId
  ? Number(numericJobId)
  : stableNumericId([companyName, jobTitle, jobUrl, text(form.pageContent).slice(0, 2000)].join("\n"));

if (!Number.isSafeInteger(jobId) || jobId <= 0) {
  throw new Error("AI extraction could not produce a safe integer Job ID.");
}

return [{
  json: {
    companyName,
    jobTitle,
    jobDescription,
    jobUrl,
    location: text(fields.location),
    contractType: text(fields.contractType),
    publishedAt: text(fields.publishedAt),
    jobId,
    source: "AI",
    master_cv: masterCv,
  },
  pairedItem: { item: 0 },
}];
